"""All settings via env vars, same philosophy as threatwatch/config.py --
no secrets hardcoded, nothing to accidentally commit.
"""
import os

FLASK_SECRET_KEY = os.environ.get("DAVEWEB_SECRET_KEY", "")

# Generated by setup_mfa.py -- a werkzeug password hash and a base32 TOTP
# secret. Never store the raw password or a plain TOTP seed here.
DAVEWEB_PASSWORD_HASH = os.environ.get("DAVEWEB_PASSWORD_HASH", "")
DAVEWEB_TOTP_SECRET = os.environ.get("DAVEWEB_TOTP_SECRET", "")

# D.A.V.E. already runs its own API server (jarvis_v2/api_server.py) on
# this port -- daveweb proxies chat into it instead of importing query.py
# cold into a second process (which would mean two processes fighting over
# the same Chroma/Ollama connections for no benefit). Same password that
# api_server.py itself checks against -- set it here too so daveweb can
# log into it on your behalf.
DAVE_API_BASE = os.environ.get("DAVE_API_BASE", "http://127.0.0.1:8420")
DAVE_GUI_PASSWORD = os.environ.get("DAVE_GUI_PASSWORD", "")

# Session lifetime -- short on purpose. This dashboard is reachable from
# the open internet via Tailscale Funnel; a stolen laptop with a week-old
# cookie is a bigger problem than logging back in more often.
SESSION_LIFETIME_HOURS = int(os.environ.get("DAVEWEB_SESSION_HOURS", "12"))

# 8420 is already taken by api_server.py on this box -- 8421 is daveweb's
# own default so the two never collide out of the box.
HOST = os.environ.get("DAVEWEB_HOST", "127.0.0.1")
PORT = int(os.environ.get("DAVEWEB_PORT", "8421"))
